const body = $json.body || $json;

// Format WAHA: body.event === 'message', body.payload.body, body.payload.from
if (!body.payload || body.payload.fromMe) {
  return [];
}

const text = (body.payload.body || '').trim().toLowerCase();
const sender = body.payload.from;
const senderName = body.payload._data?.notifyName || 'Pelanggan';

let reply = '';

if (text === '1' || text.includes('layanan') || text.includes('menu 1')) {
  reply = `📋 *Layanan Kami:*
1. Pendaftaran Rawat Inap & Jalan\n2. Pemeriksaan Laboratorium\n3. Farmasi 24 Jam\n4. Medical Check Up\n\nKetik *menu* untuk kembali.`;
} else if (text === '2' || text.includes('jadwal') || text.includes('menu 2')) {
  reply = `⏰ *Jadwal Praktek Dokter:*
- Poli Umum: 24 Jam\n- Poli Spesialis: Senin - Sabtu (08.00 - 20.00)\n- IGD: 24 Jam\n\nKetik *menu* untuk kembali.`;
} else if (text === '3' || text.includes('cs') || text.includes('call center') || text.includes('admin') || text.includes('menu 3')) {
  reply = `📞 *Call Center & Bantuan Petugas:*
Petugas Customer Service kami siap melayani Anda.\n\nSilakan klik tautan berikut untuk terhubung langsung:\n👉 https://wa.me/6281234567890?text=Halo%20Admin,%20saya%20memerlukan%20bantuan%20CS\n\nAtau hubungi Hotline: *(021) 555-1914*`;
} else {
  reply = `Halo *${senderName}*! 👋\nSelamat datang di Layanan Pelanggan RSU Catharina 1914.\n\nSilakan pilih menu dengan membalas angka/pesan berikut:\n\n*1.* Info Layanan Rumah Sakit\n*2.* Jadwal Praktek & Poli\n*3.* 📞 Hubungi Call Center / Petugas CS\n\nKetik angka *1*, *2*, atau *3* untuk memilih.`;
}

return [{
  json: {
    session: 'default',
    chatId: sender,
    text: reply
  }
}];
